// Keep - plain JS frontend (no framework, no build step beyond copy).
'use strict';

const state = {
  notes: [],
  view: 'notes', // notes | reminders | archive | trash
  search: '',
};

const $ = (sel) => document.querySelector(sel);

function el(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined && text !== null) node.textContent = text;
  return node;
}

function visibleInView(note) {
  const q = state.search.trim().toLowerCase();
  const haystack = `${note.title} ${note.content}`.toLowerCase();
  const matchesSearch = !q || haystack.includes(q);
  switch (state.view) {
    case 'trash':
      return !!note.deletedAt && matchesSearch;
    case 'archive':
      return !note.deletedAt && !!note.archived && matchesSearch;
    case 'reminders':
      return !note.deletedAt && !note.archived && !!note.reminder && matchesSearch;
    default:
      return !note.deletedAt && !note.archived && matchesSearch;
  }
}

function noteActionButtons(note) {
  const wrap = el('div', 'note-actions');
  const mk = (label, title, onClick) => {
    const b = el('button', 'note-action-btn');
    b.setAttribute('aria-label', label);
    b.title = title;
    b.innerHTML =
      '<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path fill="currentColor" d="' +
      (label === 'Pin'
        ? 'M16.59 7.58 10 14.17V21h-1.17l-4-4V10h6.83l6.59-6.59L18.59 2 15 5.59 11.41 2 9.94 3.47 13.47 7l-3.53 3.53 1.47 1.47L15 8.47 18.59 12l-1.47 1.47z'
        : label === 'Archive'
        ? 'M20.54 5.23 19.15 3.55A1 1 0 0 0 18.31 3H5.69a1 1 0 0 0-.84.55L3.46 5.23A2 2 0 0 0 3 6.5V19a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6.5a2 2 0 0 0-.46-1.27zM6.31 5l.9-1.5h9.58l.9 1.5H6.31zM19 19H5V9h14v10z'
        : label === 'Unarchive'
        ? 'M20.54 5.23 19.15 3.55A1 1 0 0 0 18.31 3H5.69a1 1 0 0 0-.84.55L3.46 5.23A2 2 0 0 0 3 6.5V19a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6.5a2 2 0 0 0-.46-1.27zM6.31 5l.9-1.5h9.58l.9 1.5H6.31zM19 19H5V9h14v10zM5 12h14v2H5z'
        : label === 'Delete'
        ? 'M6 19c0 1.1.9 2 2 2h8c1.1 0 2-.9 2-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z'
        : label === 'Restore'
        ? 'M13 3a9 9 0 0 0-9 9H1l3.89 3.89.07.14L9 12H6c0-3.87 3.13-7 7-7s7 3.13 7 7-3.13 7-7 7c-1.93 0-3.68-.79-4.94-2.06l-1.42 1.42A8.954 8.954 0 0 0 13 21a9 9 0 0 0 0-18zm-1 5v5l4.28 2.54.72-1.21-3.5-2.08V8H12z'
        : label === 'Unpin'
        ? 'M16.59 7.58 10 14.17V21h-1.17l-4-4V10h6.83l6.59-6.59L18.59 2 15 5.59 11.41 2 9.94 3.47 13.47 7l-3.53 3.53 1.47 1.47L15 8.47 18.59 12l-1.47 1.47z'
        : label === 'Edit'
        ? 'M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04a1 1 0 0 0 0-1.41l-2.34-2.34a1 1 0 0 0-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z'
        : '') +
      '</path></svg>';
    b.addEventListener('click', (e) => {
      e.stopPropagation();
      onClick();
    });
    wrap.appendChild(b);
    return b;
  };

  if (state.view === 'trash') {
    mk('Restore', 'Restore', () => api(`notes/${note.id}/restore`, 'POST').then(load));
    mk('Delete', 'Delete forever', () => api(`notes/${note.id}`, 'DELETE').then(load));
    return wrap;
  }

  mk(note.pinned ? 'Unpin' : 'Pin', note.pinned ? 'Unpin' : 'Pin', () =>
    api(`notes/${note.id}/pin`, 'POST').then(load)
  );
  mk(note.archived ? 'Unarchive' : 'Archive', note.archived ? 'Unarchive' : 'Archive', () =>
    api(`notes/${note.id}/archive`, 'POST').then(load)
  );
  mk('Edit', 'Edit', () => openEditor(note));
  mk('Delete', 'Delete note', () => deleteNote(note));
  return wrap;
}

function render() {
  const notes = state.notes.filter(visibleInView);

  $('#pinned-section').style.display = state.view === 'notes' ? '' : 'none';
  $('#others-section').style.display = state.view === 'notes' ? '' : 'none';
  $('#notes-loading').style.display = 'none';

  if (state.view === 'notes') {
    const pinned = notes.filter((n) => n.pinned);
    const others = notes.filter((n) => !n.pinned);
    renderGrid('#pinned-notes', pinned, 'No pinned notes');
    renderGrid('#others-notes', others, 'No notes yet');
  } else {
    const titles = { reminders: 'Reminders', archive: 'Archive', trash: 'Trash' };
    const title = document.querySelector(`.notes-section h2`);
    title.textContent = titles[state.view];
    renderGrid('#others-notes', notes, 'Nothing here');
    $('#others-section').style.display = '';
    $('#pinned-section').style.display = 'none';
  }
}

function renderGrid(selector, notes, emptyText) {
  const grid = $(selector);
  grid.innerHTML = '';
  if (!notes.length) {
    grid.appendChild(el('div', 'empty-hint', emptyText));
    return;
  }
  for (const note of notes) {
    const card = el('div', 'note-card');
    card.dataset.id = note.id;
    if (note.color) card.style.backgroundColor = note.color;
    if (note.title) card.appendChild(el('h3', 'note-title', note.title));
    if (note.content) card.appendChild(el('p', 'note-content', note.content));
    card.appendChild(noteActionButtons(note));
    card.addEventListener('click', () => openEditor(note));
    grid.appendChild(card);
  }
}

function openEditor(note) {
  $('#composer-title').value = note.title || '';
  $('#composer-content').value = note.content || '';
  $('#composer').dataset.editing = note.id;
  $('#composer').scrollIntoView({ behavior: 'smooth', block: 'center' });
  $('#composer-content').focus();
}

function closeComposer() {
  const title = $('#composer-title').value.trim();
  const content = $('#composer-content').value.trim();
  const editingId = $('#composer').dataset.editing;

  if (editingId) {
    if (title || content) {
      api(`notes/${editingId}`, 'PATCH', { title, content }).then(load);
    }
    delete $('#composer').dataset.editing;
  } else if (title || content) {
    api('notes', 'POST', { title, content }).then(load);
  }
  $('#composer-title').value = '';
  $('#composer-content').value = '';
}

function deleteNote(note) {
  api(`notes/${note.id}`, 'DELETE')
    .then(load)
    .then(() => showSnackbar(`"${note.title || 'Untitled'}" deleted`, () => {
      api(`notes/${note.id}/restore`, 'POST').then(load);
    }));
}

let snackbarTimer = null;
function showSnackbar(message, onAction) {
  const bar = $('#snackbar');
  bar.innerHTML = '';
  bar.appendChild(el('span', '', message));
  if (onAction) {
    const btn = el('button', 'snackbar-action', 'Undo');
    btn.addEventListener('click', () => {
      hideSnackbar();
      onAction();
    });
    bar.appendChild(btn);
  }
  bar.style.display = 'flex';
  clearTimeout(snackbarTimer);
  snackbarTimer = setTimeout(hideSnackbar, 4000);
}

function hideSnackbar() {
  $('#snackbar').style.display = 'none';
}

function api(path, method = 'GET', body) {
  const opts = { method, headers: { 'Content-Type': 'application/json' } };
  if (body !== undefined) opts.body = JSON.stringify(body);
  return fetch(`/api/${path}`, opts).then((res) => {
    if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
    return res.json();
  });
}

async function load() {
  state.notes = await api('notes');
  render();
}

function bind() {
  $('#menu-button').addEventListener('click', () => {
    $('#sidebar').classList.toggle('open');
    $('#sidebar').style.display = $('#sidebar').style.display === 'none' ? '' : 'none';
  });

  document.querySelectorAll('.nav-item').forEach((item) => {
    item.addEventListener('click', () => {
      document.querySelectorAll('.nav-item').forEach((i) => i.classList.remove('active'));
      item.classList.add('active');
      state.view = item.dataset.view;
      render();
    });
  });

  $('#search-input').addEventListener('input', (e) => {
    state.search = e.target.value;
    render();
  });

  $('#composer-content').addEventListener('keydown', (e) => {
    if (e.key === 'Escape') closeComposer();
  });

  $('#composer-close').addEventListener('click', closeComposer);

  $('#composer-title').addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      closeComposer();
    }
  });

  $('#settings-button').addEventListener('click', () => showSnackbar('Settings'));
  $('#list-view-button').addEventListener('click', () => showSnackbar('View toggled'));
}

bind();
load();

{
  "name": "keep-backend",
  "version": "0.1.0",
  "private": true,
  "description": "Keep note app - zero-dependency Node.js backend",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  }
