'use strict';

// Keep backend - zero-dependency Node.js server.
// Only http, fs, path, url, crypto are used. Data is a JSON file.

const http = require('http');
const fs = require('fs');
const path = require('path');
const url = require('url');
const crypto = require('crypto');

const PORT = parseInt(process.env.PORT, 10) || 43100;
const FRONTEND_DIST = path.resolve(__dirname, '..', 'frontend', 'dist');
const DATA_DIR = path.join(__dirname, 'data');
const DB_FILE = path.join(DATA_DIR, 'db.json');

// ---------------------------------------------------------------- persistence

function loadDb() {
  try {
    const raw = fs.readFileSync(DB_FILE, 'utf8');
    const data = JSON.parse(raw);
    if (!data || !Array.isArray(data.notes)) throw new Error('invalid db shape');
    return data;
  } catch (err) {
    console.error(`[db] failed to load ${DB_FILE}: ${err.message}`);
    process.exit(1);
  }
}

function saveDb() {
  fs.mkdirSync(DATA_DIR, { recursive: true });
  const tmp = `${DB_FILE}.${process.pid}.tmp`;
  fs.writeFileSync(tmp, JSON.stringify(db, null, 2), 'utf8');
  fs.renameSync(tmp, DB_FILE);
}

const db = loadDb();

function nowIso() {
  return new Date().toISOString();
}

function normalizeNote(note) {
  return {
    id: note.id,
    title: note.title || '',
    content: note.content || '',
    pinned: !!note.pinned,
    archived: !!note.archived,
    deletedAt: note.deletedAt || null,
    reminder: note.reminder || null,
    labels: Array.isArray(note.labels) ? note.labels : [],
    color: note.color || null,
    createdAt: note.createdAt || nowIso(),
    updatedAt: note.updatedAt || nowIso(),
  };
}

// -------------------------------------------------------------------- router

const routes = [];

function route(method, pattern, handler) {
  routes.push({ method, pattern, handler });
}

function json(res, status, body) {
  const payload = JSON.stringify(body);
  res.writeHead(status, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    req.on('data', (c) => chunks.push(c));
    req.on('end', () => {
      const raw = Buffer.concat(chunks).toString('utf8');
      if (!raw) return resolve({});
      try {
        resolve(JSON.parse(raw));
      } catch (err) {
        reject(err);
      }
    });
    req.on('error', reject);
  });
}

function findNote(id) {
  return db.notes.find((n) => n.id === id) || null;
}

// GET /api/health
route('GET', /^\/api\/health$/, (req, res) => {
  json(res, 200, { status: 'ok' });
});

// GET /api/notes
route('GET', /^\/api\/notes$/, (req, res) => {
  json(res, 200, { notes: db.notes.map(normalizeNote) });
});

// POST /api/notes
route('POST', /^\/api\/notes$/, async (req, res) => {
  let body;
  try {
    body = await readBody(req);
  } catch {
    return json(res, 400, { error: 'invalid JSON body' });
  }
  const note = normalizeNote({
    id: crypto.randomUUID(),
    title: (body.title || '').toString().slice(0, 2000),
    content: (body.content || '').toString().slice(0, 20000),
    createdAt: nowIso(),
    updatedAt: nowIso(),
  });
  db.notes.unshift(note);
  saveDb();
  json(res, 201, { note });
});

// GET /api/notes/:id
route('GET', /^\/api\/notes\/([^/]+)$/, (req, res, m) => {
  const note = findNote(decodeURIComponent(m[1]));
  if (!note) return json(res, 404, { error: 'note not found' });
  json(res, 200, { note: normalizeNote(note) });
});

// PATCH /api/notes/:id
route('PATCH', /^\/api\/notes\/([^/]+)$/, async (req, res, m) => {
  const note = findNote(decodeURIComponent(m[1]));
  if (!note) return json(res, 404, { error: 'note not found' });
  let body;
  try {
    body = await readBody(req);
  } catch {
    return json(res, 400, { error: 'invalid JSON body' });
  }
  if (body.title !== undefined) note.title = body.title.toString().slice(0, 2000);
  if (body.content !== undefined) note.content = body.content.toString().slice(0, 20000);
  if (body.color !== undefined) note.color = body.color ? String(body.color) : null;
  if (body.labels !== undefined) note.labels = Array.isArray(body.labels) ? body.labels.map(String) : [];
  if (body.reminder !== undefined) note.reminder = body.reminder ? String(body.reminder) : null;
  note.updatedAt = nowIso();
  saveDb();
  json(res, 200, { note: normalizeNote(note) });
});

// DELETE /api/notes/:id (soft delete -> trash)
route('DELETE', /^\/api\/notes\/([^/]+)$/, (req, res, m) => {
  const note = findNote(decodeURIComponent(m[1]));
  if (!note) return json(res, 404, { error: 'note not found' });
  note.deletedAt = nowIso();
  note.updatedAt = nowIso();
  saveDb();
  json(res, 200, { note: normalizeNote(note) });
});

// POST /api/notes/:id/restore
route('POST', /^\/api\/notes\/([^/]+)\/restore$/, (req, res, m) => {
  const note = findNote(decodeURIComponent(m[1]));
  if (!note) return json(res, 404, { error: 'note not found' });
  note.deletedAt = null;
  note.updatedAt = nowIso();
  saveDb();
  json(res, 200, { note: normalizeNote(note) });
});

// POST /api/notes/:id/archive (body may include archived true/false)
route('POST', /^\/api\/notes\/([^/]+)\/archive$/, async (req, res, m) => {
  const note = findNote(decodeURIComponent(m[1]));
  if (!note) return json(res, 404, { error: 'note not found' });
  let body = {};
  try {
    body = await readBody(req);
  } catch {
    // tolerate missing body
  }
  note.archived = body.archived === undefined ? true : !!body.archived;
  note.updatedAt = nowIso();
  saveDb();
  json(res, 200, { note: normalizeNote(note) });
});

// POST /api/notes/:id/pin (body may include pinned true/false)
route('POST', /^\/api\/notes\/([^/]+)\/pin$/, async (req, res, m) => {
  const note = findNote(decodeURIComponent(m[1]));
  if (!note) return json(res, 404, { error: 'note not found' });
  let body = {};
  try {
    body = await readBody(req);
  } catch {
    // tolerate missing body
  }
  note.pinned = body.pinned === undefined ? true : !!body.pinned;
  note.updatedAt = nowIso();
  saveDb();
  json(res, 200, { note: normalizeNote(note) });
});

// ------------------------------------------------------------------ static

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
};

function serveStatic(req, res, pathname) {
  let rel = pathname === '/' ? '/index.html' : pathname;
  // resolve inside frontend/dist only
  const filePath = path.normalize(path.join(FRONTEND_DIST, rel));
  if (!filePath.startsWith(FRONTEND_DIST)) {
    res.writeHead(403);
    return res.end('Forbidden');
  }
  fs.readFile(filePath, (err, data) => {
    if (err) {
      if (pathname !== '/') {
        return serveStatic(req, res, '/');
      }
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      return res.end('Not Found');
    }
    const ext = path.extname(filePath).toLowerCase();
    res.writeHead(200, { 'Content-Type': MIME[ext] || 'application/octet-stream' });
    res.end(data);
  });
}

// ----------------------------------------------------------------- server

const server = http.createServer((req, res) => {
  const parsed = url.parse(req.url || '/', true);
  const pathname = parsed.pathname || '/';

  for (const r of routes) {
    const m = pathname.match(r.pattern);
    if (m && r.method === req.method) {
      return r.handler(req, res, m);
    }
  }

  if (pathname.startsWith('/api/')) {
    return json(res, 404, { error: 'not found' });
  }

  if (req.method === 'GET') {
    return serveStatic(req, res, pathname);
  }

  res.writeHead(405, { 'Content-Type': 'text/plain; charset=utf-8' });
  res.end('Method Not Allowed');
});

server.listen(PORT, () => {
  console.log(`Keep backend listening on http://127.0.0.1:${PORT}`);
  console.log(`Serving frontend from ${FRONTEND_DIST}`);
  console.log(`Loaded ${db.notes.length} note(s) from ${DB_FILE}`);
});

function shutdown() {
  server.close(() => process.exit(0));
  setTimeout(() => process.exit(0), 2000).unref();
}
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);

