function renderGrid(selector, notes, emptyText) {
  const grid = $(selector);
  grid.innerHTML = '';
  if (!notes.length) {
    grid.appendChild(el('div', 'empty-hint', emptyText));
    return;
  }
  for (const note of notes) {
    const card = el('div', 'note-card');
    card.dataset.id = note.id;
    if (note.color) card.style.backgroundColor = note.color;
    if (note.title) card.appendChild(el('h3', 'note-title', note.title));
    if (note.content) card.appendChild(el('p', 'note-content', note.content));
    card.appendChild(noteActionButtons(note));
    card.addEventListener('click', () => openEditor(note));
    // REQ-2.3.1: only the hovered card carries a "More options" button so the
    // dropdown's "Delete Note" action always targets the note under the mouse.
    card.addEventListener('mouseenter', () => addMoreOptionsButton(card, note));
    card.addEventListener('mouseleave', () => {
      const btn = card.querySelector('.more-menu-btn');
      if (btn) btn.remove();
    });
    grid.appendChild(card);
  }
}

// ------------------------------------------------------ More options dropdown

function closeMoreMenu() {
  const menu = document.querySelector('.more-menu');
  if (menu) menu.remove();
}

function addMoreOptionsButton(card, note) {
  // keep at most one trigger in the DOM at a time
  document.querySelectorAll('.more-menu-btn').forEach((b) => b.remove());
  const actions = card.querySelector('.note-actions');
  if (!actions || actions.querySelector('.more-menu-btn')) return;
  const btn = el('button', 'note-action-btn more-menu-btn');
  btn.setAttribute('aria-label', 'More options');
  btn.title = 'More options';
  btn.innerHTML =
    '<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path fill="currentColor" d="M12 8c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm0 2c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2zm0 6c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2z"/></svg>';
  btn.addEventListener('click', (e) => {
    e.stopPropagation();
    const open = document.querySelector('.more-menu');
    if (open && open.closest('.note-card') === card) {
      closeMoreMenu();
      return;
    }
    openMoreMenu(card, note);
  });
  actions.appendChild(btn);
}

function openMoreMenu(card, note) {
  closeMoreMenu();
  const menu = el('div', 'more-menu');
  menu.setAttribute('role', 'menu');
  const item = el('button', 'more-menu-item', 'Delete Note');
  item.setAttribute('role', 'menuitem');
  item.addEventListener('click', (e) => {
    e.stopPropagation();
    closeMoreMenu();
    deleteNote(note);
  });
  menu.appendChild(item);
  card.appendChild(menu);
  document.addEventListener('click', onDocClick, true);
}

function onDocClick(e) {
  const menu = document.querySelector('.more-menu');
  if (!menu) return;
  if (menu.contains(e.target) || (e.target.closest && e.target.closest('.more-menu-btn'))) return;
  closeMoreMenu();
  document.removeEventListener('click', onDocClick, true);
}

