// ------------------------------------------------------------- trash lifecycle

const TRASH_TTL_MS = 7 * 24 * 60 * 60 * 1000; // automatic deletion after 7 days

// REQ-2.3.3: permanently remove notes that have been in the trash longer than 7 days.
function purgeExpiredTrash() {
  const cutoff = Date.now() - TRASH_TTL_MS;
  let changed = false;
  db.notes = db.notes.filter((n) => {
    if (!n.deletedAt) return true;
    const t = Date.parse(n.deletedAt);
    if (Number.isNaN(t) || t < cutoff) {
      changed = true;
      return false;
    }
    return true;
  });
  if (changed) saveDb();
}

