// DELETE /api/notes/:id/forever (permanent delete, used by the Trash view)
route('DELETE', /^\/api\/notes\/([^/]+)\/forever$/, (req, res, m) => {
  const note = findNote(decodeURIComponent(m[1]));
  if (!note) return json(res, 404, { error: 'note not found' });
  db.notes = db.notes.filter((n) => n.id !== note.id);
  saveDb();
  json(res, 200, { note: normalizeNote(note) });
});

// DELETE /api/trash (empty trash)
route('DELETE', /^\/api\/trash$/, (req, res) => {
  const before = db.notes.length;
  db.notes = db.notes.filter((n) => !n.deletedAt);
  const removed = before - db.notes.length;
  if (removed > 0) saveDb();
  json(res, 200, { removed });
});

