// REQ-2.5.1: the Archive action moves the note to the archive list and shows
// a notification with an Undo action (posts archived:false to restore it).
mk(note.archived ? 'Unarchive' : 'Archive', note.archived ? 'Unarchive' : 'Archive', () => {
  api(`notes/${note.id}/archive`, 'POST')
    .then(load)
    .then(() => showSnackbar('Note archived', () =>
      api(`notes/${note.id}/archive`, 'POST', { archived: false })
        .then(load)
        .then(() => showSnackbar('Action undone'))
    ));
});

arguments.new_string:
// REQ-2.5.1: the Archive action moves the note to the archive list and shows
// a notification with an Undo action (posts archived:false to restore it).
// REQ-2.5.4: on the archived notes list the same button becomes Unarchive and
// posts archived:false so the note leaves the archived list and returns to
// the main notes list.
mk(note.archived ? 'Unarchive' : 'Archive', note.archived ? 'Unarchive' : 'Archive', () => {
  const wasArchived = note.archived;
  api(`notes/${note.id}/archive`, 'POST', wasArchived ? { archived: false } : undefined)
    .then(load)
    .then(() => {
      if (!wasArchived) {
        showSnackbar('Note archived', () =>
          api(`notes/${note.id}/archive`, 'POST', { archived: false })
            .then(load)
            .then(() => showSnackbar('Action undone'))
        );
      }
    });
});

