const NOTE_COLORS = [
  { name: 'Default', value: null },
  { name: 'Light green', value: '#ccff90' },
  { name: 'Light blue', value: '#aecbfa' },
  { name: 'Light yellow', value: '#fff475' },
  { name: 'Light pink', value: '#f28b82' },
  { name: 'Light purple', value: '#d7aefb' },
  { name: 'Light teal', value: '#a7ffeb' },
  { name: 'Light orange', value: '#fbbc04' },
];

function closeColorPalette() {
  const palette = document.querySelector('.color-palette');
  if (palette) palette.remove();
  document.removeEventListener('click', onPaletteDocClick, true);
  document.removeEventListener('keydown', onPaletteKey, true);
}

function onPaletteKey(e) {
  if (e.key === 'Escape') {
    closeColorPalette();
    document.querySelector('.note-card:hover .note-actions')?.focus();
  }
}

function onPaletteDocClick(e) {
  const palette = document.querySelector('.color-palette');
  if (!palette) return;
  if (palette.contains(e.target) || (e.target.closest && e.target.closest('.color-btn'))) return;
  closeColorPalette();
}

function openColorPalette(note, trigger) {
  closeColorPalette();
  const palette = el('div', 'color-palette');
  palette.setAttribute('role', 'menu');
  for (const c of NOTE_COLORS) {
    const swatch = el('button', 'color-swatch');
    swatch.setAttribute('role', 'menuitem');
    swatch.setAttribute('aria-label', c.name);
    swatch.title = c.name;
    swatch.dataset.color = c.value || '';
    swatch.style.backgroundColor = c.value || '#ffffff';
    // a thin border so "Default" (white) stays visible against the menu
    if (!c.value) swatch.style.border = '1px solid var(--border)';
    swatch.addEventListener('click', (e) => {
      e.stopPropagation();
      closeColorPalette();
      const color = c.value;
      if (color) {
        note.color = color; // optimistic re-render
        render();
        api(`notes/${note.id}`, 'PATCH', { color }).then(load).catch(() => load());
      } else {
        api(`notes/${note.id}`, 'PATCH', { color: null }).then(load);
      }
    });
    palette.appendChild(swatch);
  }
  document.body.appendChild(palette);
  if (trigger) {
    const rect = trigger.getBoundingClientRect();
    palette.style.top = `${rect.bottom + 4}px`;
    palette.style.left = `${Math.min(rect.left, window.innerWidth - palette.offsetWidth - 8)}px`;
  }
  document.addEventListener('click', onPaletteDocClick, true);
  document.addEventListener('keydown', onPaletteKey, true);
}

