function closeLabelsDialog() {
  const dialog = document.querySelector('.labels-dialog');
  if (dialog) dialog.remove();
  document.removeEventListener('click', onLabelsDocClick, true);
  document.removeEventListener('keydown', onLabelsKey, true);
}

function onLabelsKey(e) {
  if (e.key === 'Escape') closeLabelsDialog();
}

function onLabelsDocClick(e) {
  const dialog = document.querySelector('.labels-dialog');
  if (!dialog) return;
  if (dialog.contains(e.target)) return;
  closeLabelsDialog();
}

// REQ-2.7.1: the "Change labels" dialog lists every known label as a native
// checkbox. Checking a box assigns the label to the note (optimistic re-render
// + PATCH /api/notes/:id {labels}), unchecking removes it (REQ-2.7.2).
function openLabelsDialog(note) {
  closeLabelsDialog();
  const overlay = el('div', 'labels-dialog');
  overlay.setAttribute('role', 'dialog');
  overlay.setAttribute('aria-label', 'Change labels');
  overlay.appendChild(el('div', 'labels-dialog-title', 'Change labels'));
  const list = el('div', 'labels-list');
  for (const label of LABEL_CATALOG) {
    const row = el('label', 'label-option');
    const input = document.createElement('input');
    input.type = 'checkbox';
    input.value = label;
    input.checked = (note.labels || []).includes(label);
    input.addEventListener('change', () => {
      const labels = (note.labels || []).slice();
      if (input.checked) {
        if (!labels.includes(label)) labels.push(label);
      } else {
        const i = labels.indexOf(label);
        if (i !== -1) labels.splice(i, 1);
      }
      note.labels = labels;
      render();
      api(`notes/${note.id}`, 'PATCH', { labels }).then(load).catch(() => load());
    });
    row.appendChild(input);
    row.appendChild(el('span', '', label));
    list.appendChild(row);
  }
  overlay.appendChild(list);
  const footer = el('div', 'labels-dialog-footer');
  const closeBtn = el('button', 'text-button', 'Close');
  closeBtn.type = 'button';
  closeBtn.addEventListener('click', closeLabelsDialog);
  footer.appendChild(closeBtn);
  overlay.appendChild(footer);
  document.body.appendChild(overlay);
  document.addEventListener('click', onLabelsDocClick, true);
  document.addEventListener('keydown', onLabelsKey, true);
}

// REQ-2.7.1: label filter buttons in the sidebar. Clicking a label shows only
// the notes carrying it (the filtered list); clicking it again clears the
// filter. The view switches back to the notes list so the filter applies.
function renderSidebarLabels() {
  const list = $('#sidebar-labels-list');
  if (!list) return;
  list.innerHTML = '';
  for (const label of LABEL_CATALOG) {
    const btn = el('button', 'label-filter-item');
    btn.type = 'button';
    btn.dataset.label = label;
    if (state.labelFilter === label) btn.classList.add('active');
    const icon = el('span', 'nav-icon', '🏷️');
    icon.setAttribute('aria-hidden', 'true');
    btn.appendChild(icon);
    btn.appendChild(document.createTextNode(label));
    btn.addEventListener('click', () => {
      state.labelFilter = state.labelFilter === label ? null : label;
      state.view = 'notes';
      document.querySelectorAll('.nav-item').forEach((i) =>
        i.classList.toggle('active', i.dataset.view === 'notes')
      );
      render();
    });
    list.appendChild(btn);
  }
}

