      "method": "GET",
      "path": "/api/health",
      "serves": "health check"
    },
    {
      "method": "POST",
      "path": "/api/notes",
      "serves": "create a note from the Take a note editor (title + content); returns 201 with the created note, 400 on invalid JSON body"
    },
    {
      "method": "GET",
      "path": "/api/notes/:id",
      "serves": "single note JSON"
    },
    {
      "method": "PATCH",
      "path": "/api/notes/:id",
      "serves": "update an existing note's labels (and title/content/color/reminder); returns 200 with the updated note, 404 when the note does not exist, 400 on invalid JSON body"
    },
    {
      "method": "DELETE",
      "path": "/api/notes/:id",
      "serves": "soft-delete a note (moves it to the Trash); returns 200 with the note, 404 when missing"
    },
    {
      "method": "POST",
      "path": "/api/notes/:id/restore",
      "serves": "restore a deleted note from the Trash; returns 200 with the note, 404 when missing"
    },
    {
      "method": "POST",
      "path": "/api/notes/:id/archive",
      "serves": "archive or unarchive a note; returns 200 with the updated note, 404 when the note does not exist"
    },
    {
      "method": "POST",
      "path": "/api/notes/:id/pin",
      "serves": "pin or unpin a note; returns 200 with the updated note, 404 when the note does not exist"
    },
    {
      "method": "DELETE",
      "path": "/api/notes/:id/forever",
      "serves": "permanently delete a note from the Trash view; returns 200 with the note, 404 when missing"
