  const title = $('#composer-title').value.trim();
  const content = $('#composer-content').value.trim();
  const editingId = $('#composer').dataset.editing;
  // REQ-2.6.2: the pending palette color applies to the note being created.
  const pendingColor = state.composerColor;
  state.composerColor = null;
  // REQ-2.7.4: the labels chosen in the composer labels dialog apply to the
  // note being created. The backend defaults a new note to ["Reminders"], so
  // an untouched composer still creates the note with the default label.
  const pendingLabels = state.composerLabels;
  state.composerLabels = null;

  if (editingId) {
    // REQ-2.4: closing the note editor persists the edited content. Always
    // PATCH (even when a field was cleared), and only once per open session.
    delete $('#composer').dataset.editing;
    const note = state.notes.find((n) => n.id === editingId);
    if (note) {
      api(`notes/${editingId}`, 'PATCH', { title, content })
        .then(load)
        .catch(() => {});
