  } else if (title || content) {
    const body = { title, content, color: pendingColor };
    if (pendingLabels) body.labels = pendingLabels;
    api('notes', 'POST', body).then(load);
  }
  $('#composer-title').value = '';
  $('#composer-content').value = '';
