// REQ-2.7.5: "Edit Labels" dialog. Lists every label as a plain text input
// (each with a visible <label for=id> whose text is the label name, so
// getByLabel('Work editable') resolves). Renaming/create/delete mutate the
// client-side LABEL_CATALOG and any in-memory note label arrays, then re-render
// the sidebar filters and note chips so the label list reflects the change.
function closeEditLabelsDialog() {
  const dialog = document.querySelector('.edit-labels-dialog');
  if (dialog) dialog.remove();
  document.removeEventListener('click', onEditLabelsDocClick, true);
  document.removeEventListener('keydown', onEditLabelsKey, true);
}

function onEditLabelsKey(e) {
  if (e.key === 'Escape') closeEditLabelsDialog();
}

function onEditLabelsDocClick(e) {
  const dialog = document.querySelector('.edit-labels-dialog');
  if (!dialog) return;
  if (dialog.contains(e.target)) return;
  closeEditLabelsDialog();
}

function renameLabel(oldName, newName) {
  if (!newName || newName === oldName) return;
  if (LABEL_CATALOG.includes(newName)) {
    showSnackbar(`Label "${newName}" already exists`);
    return;
  }
  const i = LABEL_CATALOG.indexOf(oldName);
  if (i === -1) return;
  LABEL_CATALOG[i] = newName;
  for (const note of state.notes) {
    const j = (note.labels || []).indexOf(oldName);
    if (j !== -1) note.labels[j] = newName;
  }
  if (state.labelFilter === oldName) state.labelFilter = newName;
  render();
}

function createLabel(name) {
  const trimmed = (name || '').trim();
  if (!trimmed) return;
  if (LABEL_CATALOG.includes(trimmed)) {
    showSnackbar(`Label "${trimmed}" already exists`);
    return;
  }
  LABEL_CATALOG.push(trimmed);
  render();
}

function deleteLabel(name) {
  const i = LABEL_CATALOG.indexOf(name);
  if (i === -1) return;
  LABEL_CATALOG.splice(i, 1);
  for (const note of state.notes) {
    note.labels = (note.labels || []).filter((l) => l !== name);
  }
  if (state.labelFilter === name) state.labelFilter = null;
  render();
}

