    const row = el('div', 'edit-label-row');
    const fieldLabel = el('label', 'edit-label-name');
    fieldLabel.setAttribute('for', `edit-label-${idx}`);
    fieldLabel.textContent = label;
    const input = document.createElement('input');
    input.type = 'text';
    input.id = `edit-label-${idx}`;
    input.className = 'edit-label-input';
    input.value = label;
    input.placeholder = 'Label name';
    input.addEventListener('input', () => {
      const oldName = label;
      const newName = input.value;
      // live-rename the catalog entry so closing the dialog keeps the change
      renameLabel(oldName, newName);
      // keep the local row text in sync with the (possibly rejected) rename
      if (newName !== oldName && fieldLabel.textContent !== newName) {
        if (LABEL_CATALOG[idx] === newName) fieldLabel.textContent = newName;
