  z-index: 80;
}

.edit-labels-dialog-title {
  font-size: 15px;
  font-weight: 500;
  margin-bottom: 12px;
}

.edit-labels-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 60vh;
  overflow: auto;
}

.edit-label-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 10px;
  border-radius: 4px;
}

.edit-label-row:hover {
  background: var(--hover);
}

.edit-label-name {
  min-width: 110px;
  font-size: 14px;
  color: var(--text);
}

.edit-label-input {
  flex: 1;
  min-width: 0;
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 6px 8px;
  font-size: 14px;
  color: var(--text);
  background: #fff;
}

.edit-label-input:focus {
  outline: none;
  border-color: #1a73e8;
}

.edit-label-delete {
  border: none;
  background: transparent;
  color: #d93025;
  font-size: 13px;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 4px;
  white-space: nowrap;
}

.edit-label-delete:hover {
  background: rgba(217, 48, 37, 0.08);
}

.edit-labels-dialog-footer {
  display: flex;
  justify-content: flex-end;
  margin-top: 12px;
}

/* REQ-2.7.5: "Edit Labels" entry in the sidebar label area. */
.edit-labels-item {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 10px 12px;
  border: none;
  border-radius: 0 24px 24px 0;
  background: transparent;
  font-size: 14px;
  color: var(--text);
  cursor: pointer;
  text-align: left;
  margin-top: 4px;
}

.edit-labels-item:hover {
  background: var(--hover);
}

