document.querySelectorAll('.nav-item').forEach((item) => {
  item.addEventListener('click', () => {
    document.querySelectorAll('.nav-item').forEach((i) => i.classList.remove('active'));
    item.classList.add('active');
    state.view = item.dataset.view;
    // REQ-2.7.6.2: clicking "Notes" in the sidebar returns from a
    // label-filtered view to the full notes list (clears the active label
    // filter set by clicking a sidebar label, so all notes are shown).
    if (item.dataset.view === 'notes') state.labelFilter = null;
    render();
  });
});

