$('#search-input').addEventListener('input', (e) => {
  state.search = e.target.value;
  render();
});

// REQ-3.1: focusing the search bar reveals the suggested filters panel;
// blurring it (or pressing Escape) hides it again.
const filtersPanel = $('#suggested-filters');
$('#search-input').addEventListener('focus', () => {
  filtersPanel.hidden = false;
});
// A click inside the panel must not blur the input before the chip's click
// event fires, so suppress the default mousedown behavior there.
filtersPanel.addEventListener('mousedown', (e) => e.preventDefault());
$('#search-input').addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    filtersPanel.hidden = true;
    state.search = '';
    e.target.value = '';
    render();
  }
});
document.addEventListener('focusin', (e) => {
  if (!filtersPanel.contains(e.target) && e.target !== $('#search-input')) {
    filtersPanel.hidden = true;
  }
});
// REQ-3.1: clicking a suggested filter applies it as the note list filter
// (same behavior as the sidebar label filters), so the list shows only the
// notes that match; clicking the active chip again clears the filter.
filtersPanel.querySelectorAll('.suggested-filter-chip').forEach((chip) => {
  chip.addEventListener('click', () => {
    const label = chip.dataset.filter;
    state.labelFilter = state.labelFilter === label ? null : label;
    state.view = 'notes';
    document.querySelectorAll('.nav-item').forEach((i) =>
      i.classList.toggle('active', i.dataset.view === 'notes')
    );
    render();
  });
});

