// REQ-3.2: split text on every case-insensitive occurrence of the active search
// query and wrap each hit in <mark class="search-highlight"> so the matching
// text is highlighted in the results list. With no query (or no match) the
// text is returned unchanged, so other views are unaffected.
function highlightMatches(text, query) {
  const q = (query || '').trim().toLowerCase();
  if (!q || !text) return document.createTextNode(text || '');
  const lower = text.toLowerCase();
  const fragment = document.createDocumentFragment();
  let i = 0;
  let index;
  while ((index = lower.indexOf(q, i)) !== -1) {
    if (index > i) fragment.appendChild(document.createTextNode(text.slice(i, index)));
    const mark = document.createElement('mark');
    mark.className = 'search-highlight';
    mark.textContent = text.slice(index, index + q.length);
    fragment.appendChild(mark);
    i = index + q.length;
  }
  if (i < text.length) fragment.appendChild(document.createTextNode(text.slice(i)));
  return fragment;
}

function renderGrid(selector, notes, emptyText) {
  const grid = $(selector);
  grid.innerHTML = '';
  if (!notes.length) {
    grid.appendChild(el('div', 'empty-hint', emptyText));
    return;
  }
  for (const note of notes) {
    const card = el('div', 'note-card');
    card.dataset.id = note.id;
    if (note.color) card.style.backgroundColor = note.color;
    if (note.title) {
      const title = el('h3', 'note-title');
