// ------------------------------------------- detailed settings (REQ-4.2)

function openSettingsDialog() {
  const dialog = $('#settings-dialog');
  if (!dialog) return;
  // prefill the checkboxes from the current (per-page-load) settings
  $('#setting-new-notes-bottom').checked = !!state.settings.newNotesBottom;
  $('#setting-checked-items-bottom').checked = !!state.settings.checkedItemsBottom;
  dialog.hidden = false;
  document.addEventListener('click', onSettingsDocClick, true);
  document.addEventListener('keydown', onSettingsKey, true);
  $('#setting-new-notes-bottom').focus();
}

function closeSettingsDialog() {
  const dialog = $('#settings-dialog');
  if (dialog) dialog.hidden = true;
  document.removeEventListener('click', onSettingsDocClick, true);
  document.removeEventListener('keydown', onSettingsKey, true);
}

function onSettingsKey(e) {
  if (e.key === 'Escape') closeSettingsDialog();
}

function onSettingsDocClick(e) {
  const dialog = $('#settings-dialog');
  if (!dialog || dialog.hidden) return;
  if (dialog.contains(e.target)) return;
  closeSettingsDialog();
}

function saveSettings() {
  state.settings.newNotesBottom = $('#setting-new-notes-bottom').checked;
  state.settings.checkedItemsBottom = $('#setting-checked-items-bottom').checked;
  closeSettingsDialog();
  render();
  showSnackbar('Settings saved');
}

