/* REQ-6.1: one shared item style for every sidebar entry (nav items, label
   filters and the Edit Labels entry) so all of them get the same layout,
   icon alignment, hover state and selected-item highlight. */
.nav-item,
.label-filter-item,
.edit-labels-item {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 10px 12px;
  border: none;
  border-radius: 0 24px 24px 0;
  background: transparent;
  font-family: inherit;
  font-size: 14px;
  color: var(--text);
  cursor: pointer;
  text-align: left;
}

/* REQ-6.1: every icon occupies the same fixed column, so labels line up
   across all items regardless of the glyph's natural width. */
.nav-icon {
  flex: 0 0 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  line-height: 1;
}

.nav-item:hover,
.label-filter-item:hover,
.edit-labels-item:hover {
  background: var(--hover);
}

/* REQ-6.1: the selected item is highlighted with the Keep-style tint and a
   medium weight, consistently for nav items and active label filters. */
.nav-item.active,
.label-filter-item.active {
  background: #feefc3;
  font-weight: 500;
}

.nav-item:focus-visible,
.label-filter-item:focus-visible,
.edit-labels-item:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

