// ---------------------------------------------------------------- persistence

// Pristine seed data. Acceptance fixtures live here in their requirement-canonical
// state (active, correct labels/colors). When db.json is missing or corrupt the
// server re-seeds from this template instead of crashing, so a fresh checkout or
// a wiped data dir always starts from the canonical fixture set.
function seedDb() {
  const now = new Date().toISOString();
  const fixture = (id, title, content, extra = {}) => ({
    id,
    title,
    content,
    pinned: false,
    archived: false,
    deletedAt: null,
    reminder: null,
    labels: [],
    color: null,
    createdAt: now,
    updatedAt: now,
    ...extra,
  });
  const notes = [
    // REQ-2.1: pinned + regular listing fixtures
    fixture('seed-pinned-sprint-goals', 'Sprint goals', 'Top priority items for the sprint.', { pinned: true }),
    fixture('seed-groceries', 'Groceries', 'Milk, eggs, bread, and coffee beans.'),
    // REQ-3.1/3.2: search fixture (title/content contains "st")
    fixture('seed-study-schedule', 'Study schedule', 'Weekly study plan for the semester.'),
    // REQ-2.3.x: deletable regular notes
    fixture('seed-delete-231', 'Delete me 2.3.1', 'Temporary note for deletion flow'),
    fixture('seed-delete-232', 'Delete me 2.3.2', 'Temporary note for deletion flow'),
    fixture('seed-delete-233', 'Delete me 2.3.3', 'Temporary note for deletion flow'),
    // REQ-2.4: editable note
    fixture('seed-project-ideas', 'Project ideas', 'Initial editable content'),
    // REQ-2.5.x: archivable regular notes
    fixture('seed-archive-251', 'Travel plans 2.5.1', 'Archive workflow note'),
    fixture('seed-archive-252', 'Travel plans 2.5.2', 'Archive workflow note'),
    fixture('seed-archive-253', 'Travel plans 2.5.3', 'Archive workflow note'),
    fixture('seed-archive-254', 'Travel plans 2.5.4', 'Archive workflow note'),
    // REQ-2.6.1: colorable note (regular, default color)
    fixture('seed-garden-tasks-existing', 'Garden tasks existing', 'Color me later'),
    // REQ-2.7.1: note without the Work label
    fixture('seed-label-add-271', 'Team retro add label', 'Agenda for team retro'),
    // REQ-2.7.2: note already carrying the Work label
    fixture('seed-label-remove-272', 'Team retro remove label', 'Agenda for team retro', { labels: ['Work'] }),
    // REQ-2.7.6.3 / REQ-3.1: note with the default Reminders label
    fixture('seed-call-dentist-existing', 'Call dentist existing', 'Prepare reminders note', { labels: ['Reminders'] }),
    // REQ-2.7.6.1: note with the Work label (filtered list)
    fixture('seed-design-review', 'Design review', 'Review the new onboarding flow', { labels: ['Work'] }),
    // REQ-2.7.6.x: note without Work or Reminders
    fixture('seed-movie-list', 'Movie list', 'Dune, Inception, Spirited Away'),
    // REQ-2.8.1/2.8.2: pinnable regular notes
    fixture('seed-meeting-agenda-281', 'Meeting agenda 2.8.1', 'Agenda items for the project sync'),
    fixture('seed-meeting-agenda-282', 'Meeting agenda 2.8.2', 'Agenda items for the sprint review'),
  ];
  return { notes };
}

function loadDb() {
  try {
    const raw = fs.readFileSync(DB_FILE, 'utf8');
    const data = JSON.parse(raw);
    if (!data || !Array.isArray(data.notes)) throw new Error('invalid db shape');
    return data;
  } catch (err) {
    console.error(`[db] failed to load ${DB_FILE}: ${err.message}; re-seeding from template`);
    const fresh = seedDb();
    fs.mkdirSync(DATA_DIR, { recursive: true });
    fs.writeFileSync(DB_FILE, JSON.stringify(fresh, null, 2), 'utf8');
    return fresh;
  }
}

